<?php $impact=$data['impact']; ?>
<p class="lead">Impact follows recorded collection and distribution. Offered food is shown separately from collected food.</p><div class="page-actions"><a class="button small" href="/exports/impact/0.csv">Export CSV</a><a class="button small" href="/exports/impact/0.pdf">Download PDF</a><a class="underlined" href="/exports/impact/0.json">JSON data</a></div>
<div class="metric-grid"><?php foreach (['offered_kg'=>'Food offered (kg)','accepted_kg'=>'Food accepted (kg)','collected_kg'=>'Food collected (kg)','distributed_kg'=>'Food distributed (kg)','estimated_meals'=>'Estimated meals distributed','failed_pickups'=>'Failed pickups','successful_pickups'=>'Completed pickups','expired_count'=>'Expired listings'] as $key=>$label): ?><article class="panel metric"><p><?= e($label) ?></p><strong><?= e(number_format($impact[$key],$key==='estimated_meals' ? 0 : 2)) ?></strong></article><?php endforeach ?></div>
<article class="panel spaced"><h2>Measurement assumptions</h2><p>Estimated meals = recorded distributed kilograms ÷ <?= e($impact['meal_mass_kg']) ?> kg per meal. This is a configurable estimate, not a count of people served. Estimated waste prevented uses collected weight as a proxy; it does not prove what would otherwise have happened to the food.</p><p>Pickup success rate: <?= $impact['pickup_success_rate']!==null ? e(number_format($impact['pickup_success_rate']*100,1)) . '%' : 'No terminal pickup outcomes yet' ?>. Denominator: completed + failed + expired accepted pickups; cancelled and ongoing pickups are excluded.</p></article>
<div class="dashboard-grid"><article class="panel"><h2>Monthly food offered</h2><?php if ($impact['monthly']): ?><div class="chart-wrap"><canvas data-chart="bar" data-labels="<?= e(json_encode(array_column($impact['monthly'],'month'))) ?>" data-values="<?= e(json_encode(array_map('floatval',array_column($impact['monthly'],'offered_kg')))) ?>" data-series="Food offered (kg)" aria-label="Monthly food offered chart"></canvas></div><?php else: ?><p>No listings recorded yet.</p><?php endif ?></article><article class="panel"><h2>Food category distribution</h2><?php if ($impact['categories']): ?><div class="chart-wrap"><canvas data-chart="doughnut" data-labels="<?= e(json_encode(array_column($impact['categories'],'name'))) ?>" data-values="<?= e(json_encode(array_map('floatval',array_column($impact['categories'],'offered_kg')))) ?>" data-series="Food offered (kg)" aria-label="Food category distribution chart"></canvas></div><?php else: ?><p>No category data yet.</p><?php endif ?></article></div>
<div class="dashboard-grid spaced"><?php foreach (['donors'=>'Donor contributions','receivers'=>'Receiver contributions'] as $key=>$heading): ?><article class="panel"><h2><?= e($heading) ?></h2><?php if (!$impact[$key]): ?><p>No collected contributions yet.</p><?php endif ?><ul class="activity-list"><?php foreach ($impact[$key] as $row): ?><li><span><?= e($row['name']) ?></span><strong><?= e($row['collected_kg']) ?> kg collected</strong></li><?php endforeach ?></ul></article><?php endforeach ?></div>

<article class="panel spaced"><h2>Pickup-feasibility evaluation</h2><p>Uses predictions recorded at acceptance and subsequent completed, failed or expired outcomes. Classification threshold: score ≥ 0.25. This score is not a calibrated probability.</p><dl><?php foreach ($impact['prediction_quality'] as $metric=>$value): ?><dt><?= e(str_replace('_',' ',$metric)) ?></dt><dd><?= $value===null ? 'N/A — insufficient outcomes or class pairs' : e(number_format($value,4)) ?></dd><?php endforeach ?></dl></article>

<?php if ($impact['geography']): ?><article class="panel spaced"><h2>Geographic distribution of food offered</h2><p>Coordinates are grouped to a 0.01° grid. Values show food offered, not collected.</p><div class="map" data-points="<?= e(json_encode($impact['geography'])) ?>" aria-label="Geographic distribution map"></div></article><?php endif ?>
